    "formulaResult": "\u09b8\u09b0\u0995\u09be\u09b0\u09bf \u09b8\u09b0\u09cd\u09ac\u09cb\u099a\u09cd\u099a \u09a1\u09c7\u0995 \u09ad\u09be\u09a1\u09bc\u09be: {km} \u0995\u09bf\u09ae\u09bf\u09b0 \u099c\u09a8\u09cd\u09af {fare}",
    "formulaNote": "\u09b9\u09be\u09b0: \u09aa\u09cd\u09b0\u09a5\u09ae \u09e7\u09e6\u09e6 \u0995\u09bf\u09ae\u09bf \u09e8.\u09ef\u09eb \u099f\u09be\u0995\u09be/\u0995\u09bf\u09ae\u09bf, \u09e7\u09e6\u09e6 \u0995\u09bf\u09ae\u09bf\u09b0 \u09ac\u09c7\u09b6\u09bf \u09e8.\u09eb\u09e8 \u099f\u09be\u0995\u09be/\u0995\u09bf\u09ae\u09bf, \u09b8\u09b0\u09cd\u09ac\u09a8\u09bf\u09ae\u09cd\u09a8 \u09ad\u09be\u09a1\u09bc\u09be \u09e9\u09e8 \u099f\u09be\u0995\u09be\u0964 \u098f\u099f\u09bf \u09b8\u09b0\u09cd\u09ac\u09cb\u099a\u09cd\u099a \u09b8\u09c0\u09ae\u09be, \u0995\u09be\u0989\u09a8\u09cd\u099f\u09be\u09b0\u09c7\u09b0 \u09a6\u09be\u09ae \u09a8\u09af\u09bc \u2014 \u0985\u09aa\u09be\u09b0\u09c7\u099f\u09b0 \u0995\u09ae \u09a8\u09bf\u09a4\u09c7 \u09aa\u09be\u09b0\u09c7\u0964 \u09af\u09c7\u09ae\u09a8, \u09ac\u09b0\u09bf\u09b6\u09be\u09b2\u09c7\u09b0 \u09a1\u09c7\u0995 \u09ad\u09be\u09a1\u09bc\u09be \u09e9\u09eb\u09e6 \u099f\u09be\u0995\u09be\u0964",
    "formulaErr": "\u09e7 \u09a5\u09c7\u0995\u09c7 \u09e7,\u09e6\u09e6\u09e6 \u0995\u09bf\u09ae\u09bf\u09b0 \u09ae\u09a7\u09cd\u09af\u09c7 \u09a6\u09c2\u09b0\u09a4\u09cd\u09ac \u09b2\u09bf\u0996\u09c1\u09a8\u0964",
    "classesTitle": "\u09b2\u099e\u09cd\u099a\u09c7\u09b0 \u09b6\u09cd\u09b0\u09c7\u09a3\u09bf",
    "classOnRoutes": "\u09af\u09c7\u09b8\u09ac \u09b0\u09c1\u099f\u09c7 \u0986\u099b\u09c7",
    "noFareNote": "\u098f\u0987 \u0985\u09cd\u09af\u09be\u09aa\u09c7 \u098f\u0987 \u09b6\u09cd\u09b0\u09c7\u09a3\u09bf\u09b0 \u0995\u09cb\u09a8\u09cb \u09af\u09be\u099a\u09be\u0987\u0995\u09c3\u09a4 \u09ad\u09be\u09a1\u09bc\u09be \u09a8\u09c7\u0987\u0964",
    "rulesTitle": "\u09ad\u09be\u09a1\u09bc\u09be\u09b0 \u09a8\u09bf\u09af\u09bc\u09ae \u0993 \u09ad\u09cd\u09b0\u09ae\u09a3 \u099f\u09bf\u09aa\u09b8",
    "rule_1": "\u09a1\u09c7\u0995\u09c7\u09b0 \u099f\u09bf\u0995\u09bf\u099f \u09af\u09be\u09a4\u09cd\u09b0\u09be\u09b0 \u09a6\u09bf\u09a8 \u099f\u09be\u09b0\u09cd\u09ae\u09bf\u09a8\u09be\u09b2\u09c7 \u09ac\u09bf\u0995\u09cd\u09b0\u09bf \u09b9\u09af\u09bc \u2014 \u0985\u0997\u09cd\u09b0\u09bf\u09ae \u09ac\u09c1\u0995\u09bf\u0982 \u09b9\u09af\u09bc \u09a8\u09be\u0964 \u0995\u09c7\u09ac\u09bf\u09a8 \u09b8\u09be\u09a7\u09be\u09b0\u09a3\u09a4 \u09ab\u09cb\u09a8\u09c7 \u09e8-\u09ea \u09a6\u09bf\u09a8 \u0986\u0997\u09c7 \u09ac\u09c1\u0995 \u0995\u09b0\u09be \u09b9\u09af\u09bc, \u09aa\u09cd\u09b0\u09be\u09af\u09bc\u0987 \u09eb\u09e6% \u0985\u0997\u09cd\u09b0\u09bf\u09ae (\u09ac\u09bf\u0995\u09be\u09b6/\u09a8\u0997\u09a6) \u09a6\u09bf\u09a4\u09c7 \u09b9\u09af\u09bc\u0964",
    "rule_2": "\u09b8\u09b0\u0995\u09be\u09b0\u09bf \u09b8\u09b0\u09cd\u09ac\u09cb\u099a\u09cd\u099a \u09a1\u09c7\u0995 \u09ad\u09be\u09a1\u09bc\u09be (\u0997\u09c7\u099c\u09c7\u099f, \u09eb \u09ae\u09c7 \u09e8\u09e6\u09e8\u09ec): \u09aa\u09cd\u09b0\u09a5\u09ae \u09e7\u09e6\u09e6 \u0995\u09bf\u09ae\u09bf \u09e8.\u09ef\u09eb \u099f\u09be\u0995\u09be/\u0995\u09bf\u09ae\u09bf, \u09e7\u09e6\u09e6 \u0995\u09bf\u09ae\u09bf\u09b0 \u09ac\u09c7\u09b6\u09bf \u09e8.\u09eb\u09e8 \u099f\u09be\u0995\u09be/\u0995\u09bf\u09ae\u09bf, \u09b8\u09b0\u09cd\u09ac\u09a8\u09bf\u09ae\u09cd\u09a8 \u09ad\u09be\u09a1\u09bc\u09be \u09e9\u09e8 \u099f\u09be\u0995\u09be\u0964",
    "rule_3": "\u0995\u09c7\u09ac\u09bf\u09a8\u09c7\u09b0 \u09a6\u09be\u09ae \u09b2\u099e\u09cd\u099a, \u09ae\u09cc\u09b8\u09c1\u09ae \u0993 \u099a\u09be\u09b9\u09bf\u09a6\u09be \u0985\u09a8\u09c1\u09af\u09be\u09af\u09bc\u09c0 \u09ac\u09a6\u09b2\u09be\u09af\u09bc \u2014 \u098f\u0995\u0987 \u09b0\u09c1\u099f\u09c7 \u09ad\u09bf\u09a8\u09cd\u09a8 \u09b2\u099e\u09cd\u099a\u09c7 \u09ad\u09bf\u09a8\u09cd\u09a8 \u09a6\u09be\u09ae \u09b9\u09a4\u09c7 \u09aa\u09be\u09b0\u09c7\u0964 \u0995\u09be\u0989\u09a8\u09cd\u099f\u09be\u09b0\u09c7 \u09b8\u09ac\u09b8\u09ae\u09af\u09bc \u09a8\u09bf\u09b6\u09cd\u099a\u09bf\u09a4 \u0995\u09b0\u09c1\u09a8\u0964",
    "rule_4": "\u0988\u09a6 \u0993 \u09b8\u09b0\u0995\u09be\u09b0\u09bf \u099b\u09c1\u099f\u09bf\u09a4\u09c7 \u09ad\u09be\u09a1\u09bc\u09be \u09b8\u09be\u09a7\u09be\u09b0\u09a3\u09a4 \u09e7\u09e6-\u09e8\u09e6% \u09ac\u09be\u09a1\u09bc\u09c7 \u098f\u09ac\u0982 \u0995\u09c7\u09ac\u09bf\u09a8 \u0986\u0997\u09c7\u0987 \u09b6\u09c7\u09b7 \u09b9\u09af\u09bc\u09c7 \u09af\u09be\u09af\u09bc\u0964",
    "rule_5": "\u09b6\u09bf\u09b6\u09c1: \u09ac\u09bf\u0986\u0987\u09a1\u09ac\u09cd\u09b2\u09bf\u0989\u099f\u09bf\u098f\u09b0 \u0995\u09cb\u09a8\u09cb \u09b8\u09b0\u0995\u09be\u09b0\u09bf \u09b6\u09bf\u09b6\u09c1-\u09ad\u09be\u09a1\u09bc\u09be \u09a8\u09bf\u09af\u09bc\u09ae \u09aa\u09be\u0993\u09af\u09bc\u09be \u09af\u09be\u09af\u09bc\u09a8\u09bf\u0964 \u09eb-\u09e7\u09e8 \u09ac\u099b\u09b0 \u09ac\u09af\u09bc\u09b8\u09c0\u09a6\u09c7\u09b0 \u0985\u09b0\u09cd\u09a7\u09c7\u0995 \u09ad\u09be\u09a1\u09bc\u09be \u0993 \u09eb \u09ac\u099b\u09b0\u09c7\u09b0 \u0995\u09ae \u09ac\u09af\u09bc\u09b8\u09c0\u09a6\u09c7\u09b0 \u09ac\u09bf\u09a8\u09be\u09ae\u09c2\u09b2\u09cd\u09af\u09c7 \u09ad\u09cd\u09b0\u09ae\u09a3\u0987 \u09aa\u09cd\u09b0\u099a\u09b2\u09bf\u09a4 \u2014 \u0995\u09be\u0989\u09a8\u09cd\u099f\u09be\u09b0\u09c7 \u09a8\u09bf\u09b6\u09cd\u099a\u09bf\u09a4 \u0995\u09b0\u09c1\u09a8\u0964",
    "rule_6": "\u09a1\u09c7\u0995\u09c7 \u09ad\u09cd\u09b0\u09ae\u09a3\u09c7\u09b0 \u099c\u09a8\u09cd\u09af \u09a8\u09bf\u099c\u09c7\u09b0 \u099a\u09be\u09a6\u09b0/\u09ac\u09bf\u099b\u09be\u09a8\u09be \u09a8\u09bf\u09af\u09bc\u09c7 \u09af\u09be\u09a8; \u0995\u09c7\u09ac\u09bf\u09a8\u09c7 \u09b8\u09be\u09a7\u09be\u09b0\u09a3\u09a4 \u09ac\u09bf\u099b\u09be\u09a8\u09be \u09a5\u09be\u0995\u09c7\u0964",
    "rule_7": "\u09b8\u09a6\u09b0\u0998\u09be\u099f \u09a5\u09c7\u0995\u09c7 \u09b0\u09be\u09a4\u09c7\u09b0 \u09b2\u099e\u09cd\u099a \u09b8\u09be\u09a7\u09be\u09b0\u09a3\u09a4 \u09b8\u09a8\u09cd\u09a7\u09cd\u09af\u09be\u09af\u09bc (\u09ac\u09bf\u0995\u09c7\u09b2 \u09eb\u099f\u09be-\u09b0\u09be\u09a4 \u09ef\u099f\u09be) \u099b\u09be\u09a1\u09bc\u09c7 \u098f\u09ac\u0982 \u09ad\u09cb\u09b0\u09c7 \u09aa\u09cc\u0981\u099b\u09be\u09af\u09bc\u0964 \u09af\u09be\u09a4\u09cd\u09b0\u09be\u09b0 \u09a6\u09bf\u09a8 \u099f\u09be\u09b0\u09cd\u09ae\u09bf\u09a8\u09be\u09b2\u09c7 \u099b\u09be\u09a1\u09bc\u09be\u09b0 \u09b8\u09ae\u09af\u09bc \u09a6\u09c7\u0996\u09c7 \u09a8\u09bf\u09a8\u0964",
    "rule_8": "\u0995\u09cb\u09a8\u09cb \u09b2\u099e\u09cd\u099a \u09b8\u09b0\u0995\u09be\u09b0\u09bf \u09b8\u09b0\u09cd\u09ac\u09cb\u099a\u09cd\u099a \u09b8\u09c0\u09ae\u09be\u09b0 \u09ac\u09c7\u09b6\u09bf \u09ad\u09be\u09a1\u09bc\u09be \u09a8\u09bf\u09b2\u09c7 \u09ac\u09be \u099f\u09bf\u0995\u09bf\u099f \u09a6\u09bf\u09a4\u09c7 \u0985\u09b8\u09cd\u09ac\u09c0\u0995\u09be\u09b0 \u0995\u09b0\u09b2\u09c7 \u09b8\u09a6\u09b0\u0998\u09be\u099f\u09c7 \u09ac\u09bf\u0986\u0987\u09a1\u09ac\u09cd\u09b2\u09bf\u0989\u099f\u09bf\u098f \u09a8\u09a6\u09c0\u09ac\u09a8\u09cd\u09a6\u09b0 \u0985\u09ab\u09bf\u09b8\u09c7 \u0985\u09ad\u09bf\u09af\u09cb\u0997 \u0995\u09b0\u09c1\u09a8\u0964",
